struct LowPassFilter {
    float cutoffFrequency;
    float sampleRate;
    std::vector<float> buffer;

    LowPassFilter(float cutoffFrequency, float sampleRate) : cutoffFrequency(cutoffFrequency), sampleRate(sampleRate), buffer(0) {}

    void process(float input) {
        float alpha = 1.0f - std::exp(-2 * M_PI * cutoffFrequency / sampleRate);
        float output = alpha * input + (1 - alpha) * buffer.back();
        buffer.push_back(output);
    }
};

