struct LowPassFilter {
    double cutoffFrequency;
    double alpha;

    LowPassFilter(double cutoff, double alpha) : cutoffFrequency(cutoff), alpha(alpha) {}

    void apply(double input, double *output) {
        static std::vector<double> buffer(2);
        buffer[0] = input;
        buffer[1] = output[0];

        double filteredValue = alpha * (buffer[0] + buffer[1]) - output[0];
        output[0] = filteredValue;
    }
};

struct LowPassFilter {
    float cutoffFrequency;
    std::vector<float> coefficients;

    LowPassFilter(float cutoffFrequency) : cutoffFrequency(cutoffFrequency), coefficients(2 * cutoffFrequency + 1, 0.0f) {
        for (int i = 0; i < coefficients.size(); ++i) {
            coefficients[i] = std::pow(std::sin(M_PI * i / cutoffFrequency), 2);
        }
    }

    float process(float input) {
        float sum = 0.0f;
        for (int i = 0; i < coefficients.size(); ++i) {
            sum += coefficients[i] * input;
        }
        return sum;
    }
};

