struct LowpassFilter {
    float *inputBuffer;
    float *filteredOutputBuffer;
    size_t bufferSize;

    LowpassFilter(size_t bufferSize) : bufferSize(bufferSize), inputBuffer(new float[bufferSize]), filteredOutputBuffer(new float[bufferSize]) {
        memset(inputBuffer, 0.0f, bufferSize * sizeof(float));
        memset(filteredOutputBuffer, 0.0f, bufferSize * sizeof(float));
    }

    ~LowpassFilter() {
        delete[] inputBuffer;
        delete[] filteredOutputBuffer;
    }

    void process(float sample) {
        for (size_t i = 0; i < bufferSize - 1; ++i) {
            inputBuffer[i] = inputBuffer[i + 1];
        }
        inputBuffer[bufferSize - 1] = sample;

        float sum = 0.0f;
        for (size_t i = 0; i < bufferSize; ++i) {
            sum += inputBuffer[i];
        }
        float average = sum / bufferSize;

        for (size_t i = 0; i < bufferSize; ++i) {
            filteredOutputBuffer[i] = average;
        }
    }

    float *getFilteredOutput() {
        return filteredOutputBuffer;
    }
};

