struct LowpassFilter {
    float *buffer;
    int capacity;
    int index;

    LowpassFilter(int size) : buffer(new float[size]), capacity(size), index(0) {}

    ~LowpassFilter() {
        delete[] buffer;
    }

    void addSample(float sample) {
        if (index == capacity) {
            buffer[index % capacity] = sample;
        } else {
            buffer[index++] = sample;
        }
    }

    float processSample(float input) {
        if (index == capacity) {
            return buffer[index % capacity];
        } else {
            float sum = 0.0f;
            for (int i = 0; i < capacity; ++i) {
                sum += buffer[i];
            }
            float average = sum / capacity;
            buffer[index++] = input * (1.0f - average);
            return average;
        }
    }
};

