struct LowPassFilter {
    float cutoffFrequency;
    float sampleRate;
    std::vector<float> coefficients;

    LowPassFilter(float cutoffFrequency, float sampleRate) {
        this->cutoffFrequency = cutoffFrequency;
        this->sampleRate = sampleRate;
        calculateCoefficients();
    }

    void calculateCoefficients() {
        float omega = 2 * M_PI * cutoffFrequency / sampleRate;
        float alpha = sin(omega) / (2 * M_PI);
        coefficients.push_back(1 - alpha);
        coefficients.push_back(alpha);
    }

    float process(float input) {
        float sum = 0.0f;
        for (size_t i = 0; i < coefficients.size(); ++i) {
            sum += coefficients[i] * input;
        }
        return sum;
    }
};

