struct LowPassFilter {
    float cutoffFrequency;
    std::vector<float> coefficients;

    LowPassFilter(float cutoff, int order) {
        cutoffFrequency = cutoff;
        coefficients.resize(order + 1);
        for (int i = 0; i <= order; ++i) {
            coefficients[i] = std::pow(cutoffFrequency, -i);
        }
    }

    float process(float input) {
        static std::vector<float> buffer(1, 0.0f);
        float output = input * coefficients[0];
        for (int i = 1; i < buffer.size(); ++i) {
            output += coefficients[i] * (buffer[i - 1] - input);
        }
        buffer[0] = input;
        return output;
    }
};

