struct LowpassFilter {
    float cutoffFrequency;
    float sampleRate;

    LowpassFilter(float cutoff, float sampleRate) : cutoffFrequency(cutoff), sampleRate(sampleRate) {}

    float filter(float input) {
        float alpha = cutoffFrequency / (sampleRate * sqrt(1 + cutoffFrequency * cutoffFrequency));
        float b0 = alpha;
        float b1 = 2 * alpha * sinf(PI / sampleRate);
        float b2 = alpha;
        float a0 = 1.0f;
        float a1 = -2 * sinf(PI / sampleRate);
        float a2 = 1.0f;

        std::vector<float> buffer(3);
        buffer[0] = input;
        buffer[1] = 0.0f;
        buffer[2] = 0.0f;

        float output = b0 * input + b1 * buffer[1] + b2 * buffer[2] - a0 * buffer[0] - a1 * buffer[1] - a2 * buffer[2];
        return output;
    }
};

