struct LowpassFilter {
    float *input;
    float *output;
    float alpha;

    LowpassFilter(float alpha) : alpha(alpha), input(nullptr), output(nullptr) {}

    ~LowpassFilter() {
        if (input != nullptr) free(input);
        if (output != nullptr) free(output);
    }

    void apply(float value) {
        if (input == nullptr || output == nullptr) return;

        float prevValue = *output;
        *output = alpha * value + (1 - alpha) * prevValue;

        if (*output < 0.0f || *output > 1.0f) {
            *output = std::clamp(*output, 0.0f, 1.0f);
        }
    }

    void reset() {
        if (input == nullptr || output == nullptr) return;

        for (int i = 0; i < inputSize; ++i) {
            *output = *input;
            ++input;
            ++output;
        }
    }

private:
    static const int inputSize = 1024;
    float *input;
    float *output;
    float alpha;
};

