class LowpassFilter {
public:
    LowpassFilter() : cutoffFrequency(0.0), sampleRate(0.0) {}

    void setParameters(double cutoff, double sampleRate) {
        this->cutoffFrequency = cutoff;
        this->sampleRate = sampleRate;
    }

    double process(double input) {
        if (cutoffFrequency == 0.0 || sampleRate == 0.0) {
            return input;
        }

        double omega = 2 * M_PI * cutoffFrequency / sampleRate;
        double alpha = sin(omega) / (2 * cutoffFrequency);

        double y = input * (1 + alpha) + output * (-alpha);
        output = y;

        return y;
    }

private:
    double cutoffFrequency;
    double sampleRate;
    double output = 0.0;
};

