struct LowPassFilter {
    float cutoffFrequency;
    float sampleRate;

    LowPassFilter(float cutoff, float sampleRate) : cutoffFrequency(cutoff), sampleRate(sampleRate) {}

    float process(float input) {
        if (sampleRate == 0.0f) {
            return input;
        }

        float alpha = cutoffFrequency / (sampleRate * 2.0f * M_PI);
        std::vector<float> buffer(1, input);

        for (size_t i = 1; i < buffer.size(); ++i) {
            float output = alpha * buffer[i] + (1.0f - alpha) * buffer[i - 1];
            buffer[i] = output;
        }

        return buffer.back();
    }
};

