class LowpassFilter {
public:
    static LowpassFilter* create(uint32_t sampleRate, uint32_t cutoffFrequency) {
        LowpassFilter* filter = new LowpassFilter(sampleRate, cutoffFrequency);
        return filter;
    }

    void apply(float sample) {
        if (sampleRate_ == 0 || cutoffFrequency_ == 0) {
            return;
        }

        float alpha = (2.0f * cutoffFrequency_) / sampleRate_;
        float y_n = alpha * sample + (1.0f - alpha) * prevSample_;
        prevSample_ = y_n;

        if (y_n > 1.0f) {
            y_n = 1.0f;
        } else if (y_n < -1.0f) {
            y_n = -1.0f;
        }

        output[outputIndex_] = y_n;
        outputIndex_ = (outputIndex_ + 1) % bufferLength_;
    }

private:
    LowpassFilter(uint32_t sampleRate, uint32_t cutoffFrequency) : sampleRate_(sampleRate), cutoffFrequency_(cutoffFrequency), prevSample_(0.0f), outputIndex_(0) {}

    uint32_t sampleRate_;
    uint32_t cutoffFrequency_;
    float prevSample_;
    float output[1024];
};

