struct LowPassFilter {
    float cutoffFrequency;
    float sampleRate;
    std::vector<float> coefficients;

    LowPassFilter(float cutoffFrequency, float sampleRate) {
        this->cutoffFrequency = cutoffFrequency;
        this->sampleRate = sampleRate;
        calculateCoefficients();
    }

    void calculateCoefficients() {
        float omega = 2 * M_PI * cutoffFrequency / sampleRate;
        float alpha = sin(omega) / (2 * M_PI);
        coefficients.push_back(1 - 2 * alpha + alpha * alpha);
        coefficients.push_back(-2 * alpha);
        coefficients.push_back(1 - 2 * alpha + alpha * alpha);
    }

    float filter(float input) {
        float output = coefficients[0] * input + coefficients[1] * (*this)[1] + coefficients[2] * (*this)[2];
        (*this)[0] = input;
        (*this)[1] = output;
        return output;
    }

private:
    std::vector<float> (*this)[3];
};

class LowpassFilter {
public:
    LowpassFilter(uint cutoffFrequency, uint sampleRate) : cutoffFrequency_(cutoffFrequency), sampleRate_(sampleRate) {}

    void apply(float* input, float* output, size_t length) {
        for (size_t i = 0; i < length; ++i) {
            float filteredValue = applySample(input[i], output[i]);
            output[i] = filteredValue;
        }
    }

private:
    uint cutoffFrequency_;
    uint sampleRate_;

    float applySample(float input, float output) {
        static float previousValue = 0.0f;
        float currentValue = input;

        float alpha = 1.0f - static_cast<float>(cutoffFrequency_) / sampleRate_;

        float filteredValue = alpha * currentValue + (1.0f - alpha) * previousValue;

        previousValue = currentValue;

        return filteredValue;
    }
};

