Vector3D rotate(Vector3D v, const Vector3D& axis, float angle) {
    float sinAngle = std::sin(angle);
    float cosAngle = std::cos(angle);

    Vector3D u(axis.x, axis.y, axis.z);
    Vector3D cross = crossProduct(u, v);
    Vector3D dot = {dotProduct(u, v), 0.0f, 0.0f};

    return {
        v.x * cosAngle + cross.x * sinAngle + dot.x * (1 - cosAngle),
        v.y * cosAngle + cross.y * sinAngle + dot.y * (1 - cosAngle),
        v.z * cosAngle + cross.z * sinAngle + dot.z * (1 - cosAngle)
    };
}

