        fwrite("ERROR", sizeof(char), 5, (FILE *)fileHandle);
        buffer[3] = 1;

        fwrite(buffer, sizeof(char), 4, (FILE *)fileHandle);

        fclose((FILE *)fileHandle);
        return;
