void primeFactorization(long num, std::vector<long>& factors) {
    if (num <= 1) return;

    long factor = 2;
    while (num % factor == 0) {
        factors.push_back(factor);
        num /= factor;
    }

    factor = 3;
    while (factor * factor <= num) {
        if (num % factor == 0) {
            factors.push_back(factor);
            num /= factor;
        }
        factor += 2;
    }

    if (num > 2) {
        factors.push_back(num);
    }
}

