void applyLowpassFilter(TiffLuv* tiffLuv, int width, int height) {
    for (int y = 0; y < height; ++y) {
        for (int x = 0; x < width; ++x) {
            TiffLuv neighbor;
            if (y > 0) {
                neighbor = tiffLuv[y - 1][x];
            } else {
                neighbor = tiffLuv[height - 1][x];
            }
            if (x > 0) {
                neighbor = std::min(neighbor, tiffLuv[y][x - 1]);
            } else {
                neighbor = std::min(neighbor, tiffLuv[y][width - 1]);
            }
            tiffLuv[y][x] = (tiffLuv[y][x] + neighbor) / 2;
        }
    }
}

