void applyLowpassFilter(TIFFHeader* tiffHeader, TIFFData* tiffData) {
    const uint32_t filterWidth = 3;
    const float cutoffFrequency = 0.1f;

    for (uint32_t y = 0; y < tiffHeader->imageHeight; ++y) {
        for (uint32_t x = 0; x < tiffHeader->imageWidth; ++x) {
            float sum = 0.0f;
            for (int32_t dy = -filterWidth / 2; dy <= filterWidth / 2; ++dy) {
                for (int32_t dx = -filterWidth / 2; dx <= filterWidth / 2; ++dx) {
                    uint32_t yNew = y + dy;
                    uint32_t xNew = x + dx;
                    if (yNew >= 0 && yNew < tiffHeader->imageHeight && xNew >= 0 && xNew < tiffHeader->imageWidth) {
                        sum += tiffData->data[yNew * tiffHeader->imageWidth + xNew] / (filterWidth * filterWidth);
                    }
                }
            }
            tiffData->data[y * tiffHeader->imageWidth + x] = (sum / (filterWidth * filterWidth)) * cutoffFrequency;
        }
    }
}

