    TIFFStrip* newStrip = (TIFFStrip*)malloc(sizeof(TIFFStrip));
    newStrip->stripIndex = stripIndex;
    newStrip->dataLength = dataLength;
    newStrip->dataPtr = (void*)malloc(dataLength);
